import { SingleCoinImage } from '@cetus/ui-kit'
import { addComma, addressAbridge, cancelBubble } from '@cetus/utils'
import { Box, HStack, Text } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'

interface TokenInfo {
  account: string
  topic: 'Bought' | 'Sold' | 'Created' | 'Completed'
  amountSui: string | number
  symbol: string
  image: string
  date: string
  coin_type: string
}
interface ScrollInfoProps extends TokenInfo {
  isWrap?: boolean
}

export default function ScrollInfo({ account, topic, symbol, amountSui, image, date, coin_type, isWrap = false }: ScrollInfoProps) {
  const navigate = useNavigate()
  return (
    <Box
      w="100%"
      onClick={() => {
        navigate(`/trade/${coin_type}`)
      }}
    >
      {['Bought', 'Sold'].includes(topic) ? (
        <HStack cursor="pointer" w="100%" flexWrap={isWrap ? 'wrap' : 'nowrap'} justifyContent="center">
          <Text
            fontWeight="500"
            color="text_caption"
            onClick={e => {
              cancelBubble(e)
              navigate(`/profile/${account}`)
            }}
          >
            {addressAbridge(account)}
          </Text>
          <Text fontWeight="500" color={topic === 'Bought' ? 'primary_green' : 'primary_red'}>
            {topic}
          </Text>
          <Text fontWeight="500" color="text_caption">
            {addComma(amountSui)}
          </Text>
          <Text fontWeight="500" color="text_caption">
            SUI
          </Text>
          <Text fontWeight="500" color="text_caption">
            of
          </Text>
          <SingleCoinImage w="20px" h="20px" borderRadius="50%" imageUrl={image} />
          <Text fontWeight="500" color="text_caption">
            {symbol}
          </Text>
        </HStack>
      ) : topic === 'Created' ? (
        <HStack cursor="pointer" w="100%" flexWrap={isWrap ? 'wrap' : 'nowrap'} justifyContent="center">
          <Text
            fontWeight="500"
            color="text_caption"
            onClick={e => {
              cancelBubble(e)
              navigate(`/profile/${account}`)
            }}
          >
            {addressAbridge(account)}
          </Text>
          <Text fontWeight="500" color="primary_blue">
            {topic}
          </Text>
          <SingleCoinImage w="20px" h="20px" borderRadius="50%" imageUrl={image} />
          <Text fontWeight="500" color="text_caption">
            {symbol}
          </Text>
          <Text fontWeight="500" color="text_caption">
            on
          </Text>
          <Text fontWeight="500" color="text_caption">
            {date}
          </Text>
        </HStack>
      ) : (
        <HStack cursor="pointer" w="100%" flexWrap={isWrap ? 'wrap' : 'nowrap'} justifyContent="center">
          <SingleCoinImage w="20px" h="20px" borderRadius="50%" imageUrl={image} />
          <Text fontWeight="500" color="text_caption">
            {symbol}
          </Text>
          <Text fontWeight="500" background="status_text" bgClip="text">
            {topic}
          </Text>
          <Text fontWeight="500" color="text_caption">
            Bonding Curve
          </Text>
          <Text fontWeight="500" color="text_caption">
            {date}
          </Text>
        </HStack>
      )}
    </Box>
  )
}
